/* White is D (bottom), yellow is U (top). Each drill is generated by
   undoing a real move pattern; prior-layer invariants are tested in tests/core.cjs. */
(function(root){
const inverse = seq => seq.trim().split(/\s+/).filter(Boolean).reverse().map(m=>m.endsWith('2')?m:m.endsWith("'")?m[0]:m+"'").join(' ');
const solvedRange=(p,o,start,end)=>p.slice(start,end).every((v,i)=>v===i+start && o[i+start]===0);
const goals=[()=>true,
 c=>solvedRange(c.ep,c.eo,4,8),
 c=>goals[1](c)&&solvedRange(c.cp,c.co,4,8),
 c=>goals[2](c)&&solvedRange(c.ep,c.eo,8,12),
 c=>goals[3](c)&&c.eo.slice(0,4).every(v=>v===0),
 c=>goals[4](c)&&c.cp.slice(0,4).every((v,i)=>v===i),
 c=>c.isSolved()];
const lessons=[
 {title:'Meet your cube',tag:'EXPLORE',subtitle:'Every piece has a place. Let’s find yours.',goal:'Find a center, an edge, and a corner.',question:'How many colors does an edge piece have?',answers:['One color','Two colors','Three colors'],correct:1,nudge:'Look along the line where two faces meet.',why:'Centers name each face. Edges have two colors. Corners have three.',patterns:[''],names:['Piece detective']},
 {title:'Make the white cross',tag:'CONNECT',subtitle:'Four white edges. Four matching neighbors.',goal:'White plus on the bottom. Side colors match their centers.',question:'Where does the white-and-green edge belong?',answers:['Beside the green center','Beside any white square','Beside the blue center'],correct:0,nudge:'Find a white edge. Which center matches its other color?',why:'An edge belongs between the two centers that match its colors.',patterns:['F2','R2','L2','B2'],names:['Bring an edge home','Right edge home','Left edge home','Back edge home']},
 {title:'Solve the white corners',tag:'BUILD',subtitle:'Give each three-color piece a home.',goal:'The whole white layer matches, including the sides.',question:'What tells you where a corner belongs?',answers:['Only its white sticker','All three of its colors','The nearest empty space'],correct:1,nudge:'Look above the front-right slot. Match all three colors before turning.',why:'Lift, turn, and return puts a corner home and brings the cross back.',patterns:["R U R'","F' U' F","L' U' L","B U B'"],names:['Right corner home','Front corner home','Left corner home','Back corner home']},
 {title:'Solve the middle edges',tag:'PLAN',subtitle:'Keep your white layer safe. Build one layer higher.',goal:'The bottom two layers have matching side colors.',question:'Which edge can go in the middle layer?',answers:['An edge with yellow','An edge with no white or yellow','Any corner'],correct:1,nudge:'Look on top for an edge without yellow. Its two colors point to its slot.',why:'Move the edge aside, open its slot, and restore the white corner.',patterns:["U R U' R' U' F' U F","U' L' U L U F U' F'"],names:['Slide an edge right','Slide an edge left']},
 {title:'Make the yellow cross',tag:'SPOT',subtitle:'Turn a dot or a line into a bright yellow plus.',goal:'Four yellow edges face up. Corners can wait.',question:'Which yellow pieces matter for the cross?',answers:['The four corners','The four edges','Every side piece'],correct:1,nudge:'Look only at yellow edges. A line should run left to right; an L sits at the back-left.',why:'Open the front, work on the top, and close the front to protect the layers below.',patterns:["F R U R' U' F'","F U R U' R' F'"],names:['Line to cross','L to cross']},
 {title:'Place the yellow corners',tag:'MATCH',subtitle:'Right home first. Yellow facing up comes later.',goal:'Each top corner has the right three neighbors.',question:'Can a corner be in its home with yellow facing sideways?',answers:['Yes — check all three colors','No — yellow must face up'],correct:0,nudge:'Find a corner whose three colors match its three centers. The other corners travel around it.',why:'Three corners trade places while the finished layers come back together.',patterns:["U R U' L' U R' U' L","L' U R U' L U R' U'"],names:['Cycle three corners','Cycle the other way']},
 {title:'Finish the last layer',tag:'SHINE',subtitle:'Face yellow up. Bring the last edges home.',goal:'Every face is one color. You did the thinking!',question:'When the bottom looks mixed halfway through a trick, what helps?',answers:['Stop halfway','Finish the full pattern with the same front face','Turn the whole cube at random'],correct:1,nudge:'Keep green in front. Finish a whole corner-twist pattern before judging the bottom. Then cycle the remaining edges.',why:'Complete patterns restore what they temporarily move, while changing the pieces you need.',patterns:["R' D' R D R' D' R D U R' D' R D R' D' R D R' D' R D R' D' R D U'","R U' R U R U R U' R' U' R2","R2 U R U R' U' R' U' R' U R'"],names:['Face yellow up','Cycle the last edges','Cycle edges the other way']}
];
// A facelet round-trip catches unrecognized or mirrored pieces before parity tests.
function validate(s){
 if(typeof s!=='string'||s.length!==54||/[^URFDLB]/.test(s))return 'Paint every square with one of the six colors.';
 if('URFDLB'.split('').some(f=>s.split(f).length-1!==9))return 'Count each color: we need exactly 9 of every color.';
 if('URFDLB'.split('').some((f,i)=>s[i*9+4]!==f))return 'Keep the center colors in their starting places.';
 const c=Cube.fromString(s);
 if(c.asString()!==s || new Set(c.cp).size!==8 || new Set(c.ep).size!==12)return 'Some pieces have colors that cannot go together. Check the edges and corners, especially the back face.';
 if(c.co.reduce((a,b)=>a+b,0)%3)return 'A corner looks twisted. Check its three stickers against your real cube.';
 if(c.eo.reduce((a,b)=>a+b,0)%2)return 'One edge looks flipped. Check its two stickers against your real cube.';
 const parity=p=>p.reduce((n,v,i)=>n+p.slice(i+1).filter(x=>x<v).length,0)%2;
 if(parity(c.cp)!==parity(c.ep))return 'Two pieces seem swapped. Double-check each face. A cube taken apart may need an adult to put it back together.';
 return null;
}
const caption=m=>{const names={U:'top',D:'bottom',R:'right',L:'left',F:'front',B:'back'};return m?`Turn the ${names[m[0]]} face ${m.endsWith('2')?'halfway around':m.endsWith("'")?'a quarter-turn counterclockwise':'a quarter-turn clockwise'} — looking straight at that face.`:'';};
root.CubeLessons={lessons,goals,inverse,validate,caption};
if(typeof module!=='undefined')module.exports=root.CubeLessons;
})(typeof window!=='undefined'?window:globalThis);
